{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울특별시 동물보호 조례상 등록칩을 넣은 등록대상동물 산책 시 이름·전화번호 목걸이(인식표) 필수 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "서울특별시 동물보호 조례 제7조제3항제2호에 따르면, 소유자등은 등록대상동물을 동반하고 외출할 때 등록대상동물의 이름, 소유자의 연락처, 그 밖에 시행규칙 제12조에 따른 사항을 표시한 인식표를 등록대상동물에게 부착하여야 합니다. 따라서 몸에 등록칩을 넣었더라도 산책 시 이름·전화번호가 적힌 인식표(목걸이 등)를 부착할 의무가 있으며, 칩만으로 이를 대신할 수 있다고 규정되어 있지 않습니다. 다만 인식표에 표시할 세부 사항은 시행규칙 제12조에 따릅니다.",
          "b_ids": "동물보호:제7조제3항, 동물보호:제7조제3항제2호"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
